printf '#include <iostream>
long long factorial(int n) {
    if (n <= 0) return 0; // BUG: 0! phai bang 1
    long long res = 1;
    for (int i = 1; i <= n; ++i) res *= i;
    return res;
}
int main() {
    std::cout << factorial(5) << " " << factorial(0) << std::endl;
    return 0;
}
' > calculator_module.cpp && printf '#!/bin/bash
